package de.schaepi.puls180;
import android.os.Bundle;import android.graphics.Color;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.regex.*;
public class GuideActivity extends FontActivity {
private int page=0;private TextView heading,body,counter;private Button previous,next;private ScrollView scroll;private final ArrayList<String> pages=new ArrayList<>();private float d;
public void onCreate(Bundle b){super.onCreate(b);d=getResources().getDisplayMetrics().density;load();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding((int)(18*d),(int)(42*d),(int)(18*d),(int)(18*d));root.setBackgroundColor(Appearance.background(this));TextView title=label("Anleitung",27,true,Color.rgb(20,75,135));root.addView(title);TextView subtitle=label("Schritt für Schritt durch Puls 180",15,false,Color.rgb(80,96,115));subtitle.setPadding(0,0,0,(int)(12*d));root.addView(subtitle);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding((int)(18*d),(int)(16*d),(int)(18*d),(int)(12*d));GradientDrawable bg=new GradientDrawable();bg.setColor(Appearance.card(this));bg.setCornerRadius(16*d);bg.setStroke((int)d,Color.rgb(218,228,240));card.setBackground(bg);heading=label("",21,true,Color.rgb(20,60,105));counter=label("",13,false,Color.rgb(70,125,185));card.addView(heading);card.addView(counter);scroll=new ScrollView(this);body=label("",17,false,Appearance.text(this));body.setTextIsSelectable(true);body.setLineSpacing(0,1.15f);body.setPadding(0,(int)(14*d),0,(int)(14*d));scroll.addView(body);card.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.addView(card,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);bar.setPadding(0,(int)(10*d),0,0);previous=button("‹ Zurück",Color.rgb(70,95,125));next=button("Weiter ›",Color.rgb(25,112,220));bar.addView(previous,new LinearLayout.LayoutParams(0,-2,1));bar.addView(next,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);Button close=button("Zurück zu meinen Werten",Color.rgb(35,155,80));close.setOnClickListener(v->finish());root.addView(close);previous.setOnClickListener(v->{if(page>0){page--;render();}});next.setOnClickListener(v->{if(page<pages.size()-1){page++;render();}});setContentView(root);render();}
private TextView label(String value,float size,boolean bold,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}
private Button button(String value,int color){Button b=new Button(this);b.setText(value);b.setTextSize(17);b.setTextColor(Color.WHITE);b.setAllCaps(false);GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(12*d);b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x30ffffff),g,null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,(int)(54*d));p.setMargins((int)(4*d),(int)(4*d),(int)(4*d),(int)(4*d));b.setLayoutParams(p);return b;}
private void load(){try{int id=getResources().getIdentifier("anleitung","raw",getPackageName());try(java.io.InputStream in=getResources().openRawResource(id);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);String all=new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);Matcher m=Pattern.compile("(?m)^\\d+\\.\\s").matcher(all);ArrayList<Integer> starts=new ArrayList<>();while(m.find())starts.add(m.start());for(int i=0;i<starts.size();i++){int end=i+1<starts.size()?starts.get(i+1):all.length();pages.add(all.substring(starts.get(i),end).trim());}}}catch(Exception ignored){}if(pages.isEmpty())pages.add("1. Anleitung\n\nAnleitung konnte nicht geladen werden.");}
private void render(){String text=pages.get(page),title=text,content="";int nl=text.indexOf('\n');if(nl>=0){title=text.substring(0,nl).trim();content=text.substring(nl+1).trim();}heading.setText(title);counter.setText("Seite "+(page+1)+" von "+pages.size());body.setText(content);previous.setEnabled(page>0);next.setEnabled(page<pages.size()-1);previous.setAlpha(page>0?1f:.4f);next.setAlpha(page<pages.size()-1?1f:.4f);scroll.post(()->scroll.scrollTo(0,0));}
}




